SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci';

SET CHARACTER SET utf8mb4;

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";

START TRANSACTION;

SET time_zone = "+00:00";

SET FOREIGN_KEY_CHECKS = 0;

-- Drop de tablas en caso de que ya existan
DROP TABLE IF EXISTS `reports`;
DROP TABLE IF EXISTS `sessions`;
DROP TABLE IF EXISTS `game_categories`;
DROP TABLE IF EXISTS `favorites`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `games`;
DROP TABLE IF EXISTS `studios`;
DROP TABLE IF EXISTS `plans`;
DROP TABLE IF EXISTS `roles`;
DROP TABLE IF EXISTS `pegi`;
DROP TABLE IF EXISTS `categories`;
DROP TABLE IF EXISTS `avatars`;

-- --------------------------------------------------------
-- ESTRUCTURA DE TABLAS
-- --------------------------------------------------------

-- Avatars
CREATE TABLE `avatars` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `image_url` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Categories
CREATE TABLE `categories` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `icon` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Studios
CREATE TABLE `studios` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Pegi Ratings
CREATE TABLE `pegi` (
  `id` int NOT NULL,
  `name` varchar(255) NOT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Roles
CREATE TABLE `roles` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Subscription Plans
CREATE TABLE `plans` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `quality` varchar(10) NOT NULL,
  `gpu` varchar(100) NOT NULL,
  `fps` int NOT NULL,
  `priority` varchar(50) NOT NULL,
  `session_limit` int DEFAULT NULL, -- NULL significará ilimitado
  `storage` int NOT NULL,
  `mods` varchar(50) NOT NULL,
  `audio` varchar(50) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Games
CREATE TABLE `games` (
  `id` int NOT NULL AUTO_INCREMENT,
  `developer_id` int DEFAULT NULL,
  `publisher_id` int DEFAULT NULL,
  `pegi_id` int DEFAULT NULL,
  `steam_id` int DEFAULT NULL,
  `igdb_id` int DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `summary` text,
  `description` text,
  `cover_url` varchar(255) DEFAULT NULL,
  `banner_url` varchar(255) DEFAULT NULL,
  `hero_url` varchar(255) DEFAULT NULL,
  `logo_url` varchar(255) DEFAULT NULL,
  `metacritic_score` int DEFAULT NULL,
  `release_date` date DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `is_featured` boolean DEFAULT 0,
  `is_active` boolean DEFAULT 1,
  `slug` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug_idx` (`slug`),
  KEY `developer_id_idx` (`developer_id`),
  KEY `publisher_id_idx` (`publisher_id`),
  KEY `pegi_id_idx` (`pegi_id`),
  KEY `published_at_idx` (`published_at`),
  KEY `release_date_idx` (`release_date`),
  KEY `is_featured_idx` (`is_featured`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Users
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `plan_id` int DEFAULT NULL,
  `role_id` int DEFAULT NULL,
  `avatar_id` int DEFAULT NULL,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `token` varchar(255) DEFAULT NULL,
  `email` varchar(150) NOT NULL,
  `birth_date` date DEFAULT NULL,
  `last_login_at` timestamp NULL DEFAULT NULL,
  `is_active` boolean DEFAULT 1,
  `ban_reason` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email_idx` (`email`),
  UNIQUE KEY `username_idx` (`username`),
  KEY `plan_id_idx` (`plan_id`),
  KEY `role_id_idx` (`role_id`),
  KEY `avatar_id_idx` (`avatar_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Favorites (Pivot Table)
CREATE TABLE `favorites` (
  `user_id` int NOT NULL,
  `game_id` int NOT NULL,
  PRIMARY KEY (`user_id`, `game_id`),
  KEY `game_id_idx` (`game_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Game Categories (Pivot Table)
CREATE TABLE `game_categories` (
  `game_id` int NOT NULL,
  `category_id` int NOT NULL,
  PRIMARY KEY (`game_id`, `category_id`),
  KEY `category_id_idx` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Play Sessions
CREATE TABLE `sessions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `game_id` int DEFAULT NULL,
  `started_at` timestamp NULL DEFAULT NULL,
  `duration` int NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id_idx` (`user_id`),
  KEY `game_id_idx` (`game_id`),
  KEY `started_at_idx` (`started_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

